package net.barttolo.bwe;

import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.tags.BlockTags;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/** Fail-closed, read-only checks: unloaded chunks never get generated by scanning. */
public final class WorldChecks {
    private static final Set<net.minecraft.world.level.block.Block> SOIL = new HashSet<>(Arrays.asList(
        Blocks.GRASS_BLOCK, Blocks.DIRT, Blocks.COARSE_DIRT, Blocks.PODZOL,
        Blocks.ROOTED_DIRT, Blocks.MYCELIUM, Blocks.MUD, Blocks.CLAY,
        Blocks.SAND, Blocks.RED_SAND, Blocks.GRAVEL, Blocks.STONE,
        Blocks.ANDESITE, Blocks.GRANITE, Blocks.DIORITE,
        Blocks.DEEPSLATE, Blocks.CALCITE, Blocks.TUFF, Blocks.SNOW_BLOCK,
        Blocks.MOSS_BLOCK, Blocks.MOSS_CARPET, Blocks.PACKED_MUD,
        Blocks.TERRACOTTA, Blocks.WHITE_TERRACOTTA, Blocks.ORANGE_TERRACOTTA,
        Blocks.YELLOW_TERRACOTTA, Blocks.RED_TERRACOTTA, Blocks.BROWN_TERRACOTTA
    ));

    private WorldChecks() {}

    public record Survey(boolean ok, String reason, int groundY, int low, int high,
                         int liquids, int artificial, int unloaded, int sampled) {}

    public static int ground(ServerLevel level, int x, int z) {
        int from = level.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, x, z) - 1;
        for (int y = from; y >= Math.max(level.getMinBuildHeight(), from - 26); y--) {
            BlockState block = level.getBlockState(new BlockPos(x, y, z));
            if (SOIL.contains(block.getBlock()) || block.is(BlockTags.TERRACOTTA)) return y;
        }
        return Integer.MIN_VALUE;
    }

    public static boolean natural(BlockState state) {
        if (state.isAir() || state.getFluidState().isEmpty() &&
            (SOIL.contains(state.getBlock()) || state.is(BlockTags.TERRACOTTA)
            || state.is(BlockTags.LOGS) || state.is(BlockTags.LEAVES)
            || state.is(BlockTags.FLOWERS) || state.is(BlockTags.SAPLINGS)
                        || state.is(Blocks.GRASS) || state.is(Blocks.TALL_GRASS)
            || state.is(Blocks.FERN) || state.is(Blocks.LARGE_FERN)
            || state.is(Blocks.DEAD_BUSH) || state.is(Blocks.SNOW)
            || state.is(Blocks.VINE) || state.is(Blocks.BROWN_MUSHROOM)
            || state.is(Blocks.RED_MUSHROOM) || state.is(Blocks.CACTUS) || state.is(Blocks.AZALEA) || state.is(Blocks.FLOWERING_AZALEA)
            || state.is(Blocks.PINK_PETALS) || state.is(Blocks.BAMBOO)
            || state.is(Blocks.SUGAR_CANE))) return true;
        return false;
    }

    public static Survey scan(ServerLevel world, BlockPos center, int halfX, int halfZ, int maxHeightDifference) {
        return survey(world, center, halfX, halfZ, maxHeightDifference, 2);
    }

    public static Survey scanFull(ServerLevel world, BlockPos center, int halfX, int halfZ, int maxHeightDifference) {
        return survey(world, center, halfX, halfZ, maxHeightDifference, 1);
    }

    private static Survey survey(ServerLevel world, BlockPos center, int halfX, int halfZ, int maxHeightDifference, int stride) {
        String dim = world.dimension().location().toString();
        if (!dim.equals("minecraft:overworld")) return fail("Solo Overworld.");
        if (halfX > 32 || halfZ > 32 || halfX < 1 || halfZ < 1) return fail("Dimensiones fuera del limite.");
        BlockPos spawn = world.getSharedSpawnPos();
        // RingWorld spawns may lie on high Y; horizontal radius is safer.
        long sdX=(long)center.getX()-spawn.getX(), sdZ=(long)center.getZ()-spawn.getZ();
        if(sdX*sdX+sdZ*sdZ < (long)(160 + Math.max(halfX, halfZ))*(160 + Math.max(halfX, halfZ)))
            return fail("Zona demasiado cerca del spawn (reserva 160 bloques). ");
        WorldData data = WorldData.get(world);
        if (data.protectedFootprint(dim, center.getX()-halfX,center.getZ()-halfZ,
                center.getX()+halfX,center.getZ()+halfZ,8))
            return fail("Se cruza con una zona protegida manualmente.");
        if (data.overlapsCompleted(dim, center.getX()-halfX, center.getZ()-halfZ,
                center.getX()+halfX, center.getZ()+halfZ, 16))
            return fail("Otra estructura BWE finalizada esta demasiado cerca.");
        // Check EVERY chunk intersecting the survey area BEFORE calling getHeight.
        // Checking only corners can miss an unloaded interior chunk, causing
        // getHeight() to generate/load new terrain on the server thread.
        long minX = (long) center.getX() - halfX - 2L;
        long maxX = (long) center.getX() + halfX + 2L;
        long minZ = (long) center.getZ() - halfZ - 2L;
        long maxZ = (long) center.getZ() + halfZ + 2L;
        if (minX < -30_000_000L || maxX > 30_000_000L ||
            minZ < -30_000_000L || maxZ > 30_000_000L)
            return fail("Coordenadas fuera de los limites de Minecraft.");
        for (long cx = minX >> 4; cx <= (maxX >> 4); cx++) {
            for (long cz = minZ >> 4; cz <= (maxZ >> 4); cz++) {
                if (!world.hasChunk((int) cx, (int) cz))
                    return fail("Hay chunks sin cargar; acercate al lugar.");
            }
        }
        // All four corners must be inside the server world border.
        for (long x : new long[]{minX, maxX})
            for (long z : new long[]{minZ, maxZ})
                if (!world.getWorldBorder().isWithinBounds(new BlockPos((int)x, center.getY(), (int)z)))
                    return fail("Fuera del borde del mundo.");
        int low=Integer.MAX_VALUE, high=Integer.MIN_VALUE, liquids=0, artificial=0, sampled=0, unloaded=0;
        for (int dx=-halfX; dx<=halfX; dx+=stride) for (int dz=-halfZ; dz<=halfZ; dz+=stride) {
            int x=center.getX()+dx, z=center.getZ()+dz;
            if (!world.hasChunk(x>>4,z>>4)) { unloaded++; continue; }
            int y = ground(world,x,z);
            if (y == Integer.MIN_VALUE) return fail("No se identifico suelo natural en toda el area.");
            low=Math.min(low,y); high=Math.max(high,y); sampled++;
            for (int yy=Math.max(world.getMinBuildHeight(),y-2); yy<=Math.min(world.getMaxBuildHeight()-1,y+11); yy++) {
                BlockPos p=new BlockPos(x,yy,z);
                BlockState state=world.getBlockState(p);
                if (!state.getFluidState().isEmpty()) liquids++;
                if (state.hasBlockEntity() || !natural(state) && state.getFluidState().isEmpty()) artificial++;
            }
        }
        if (unloaded != 0) return new Survey(false,"Chunks sin cargar",0,low,high,liquids,artificial,unloaded,sampled);
        if (high-low > maxHeightDifference) return new Survey(false,"Demasiado desnivel: "+(high-low),0,low,high,liquids,artificial,0,sampled);
        if (liquids > 0) return new Survey(false,"Agua o lava en la zona",0,low,high,liquids,artificial,0,sampled);
        if (artificial > 0) return new Survey(false,"Bloques potencialmente construidos ("+artificial+")",0,low,high,liquids,artificial,0,sampled);
        int target=(low+high)/2+1;
        if (target - 4 < world.getMinBuildHeight() || target + 17 >= world.getMaxBuildHeight()) return fail("Altura fuera del mundo.");
        return new Survey(true,"Terreno apto segun comprobaciones conservadoras",target,low,high,liquids,artificial,0,sampled);
    }

    private static Survey fail(String reason) { return new Survey(false,reason,0,0,0,0,0,0,0); }
}
